create extension if not exists pgcrypto;
create table profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz default now(), updated_at timestamptz default now());
create table watchlists (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null default 'My Watchlist', created_at timestamptz default now(), updated_at timestamptz default now());
create table watchlist_items (id uuid primary key default gen_random_uuid(), watchlist_id uuid not null references watchlists(id) on delete cascade, symbol text not null, exchange text not null default 'NSE', position integer not null default 0, created_at timestamptz default now(), unique(watchlist_id,symbol,exchange));
create table portfolios (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null default 'My Portfolio', created_at timestamptz default now(), updated_at timestamptz default now());
create table portfolio_transactions (id uuid primary key default gen_random_uuid(), portfolio_id uuid not null references portfolios(id) on delete cascade, symbol text not null, exchange text not null check(exchange in ('NSE','BSE')), transaction_type text not null check(transaction_type in ('BUY','SELL')), quantity numeric(18,4) not null check(quantity>0), price numeric(18,4) not null check(price>=0), charges numeric(18,4) default 0 check(charges>=0), transacted_at timestamptz not null, notes text, created_at timestamptz default now());
create table journal_entries (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, symbol text not null, trade_date date not null, trade_type text, entry_price numeric, exit_price numeric, quantity numeric check(quantity>0), stop_loss numeric, target numeric, strategy text, setup text, entry_reason text, exit_reason text, notes text, psychology text, result text, profit_loss numeric, created_at timestamptz default now(), updated_at timestamptz default now());
create table alerts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, symbol text not null, condition_type text not null, threshold numeric, enabled boolean default true, triggered_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, body text, read_at timestamptz, created_at timestamptz default now());
create table saved_screeners (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, filters jsonb not null default '{}', created_at timestamptz default now(), updated_at timestamptz default now());
create table user_settings (user_id uuid primary key references auth.users(id) on delete cascade, preferences jsonb not null default '{}', updated_at timestamptz default now());
create index on watchlists(user_id);create index on portfolios(user_id);create index on journal_entries(user_id,trade_date desc);create index on alerts(user_id,enabled);create index on notifications(user_id,created_at desc);
alter table profiles enable row level security;alter table watchlists enable row level security;alter table watchlist_items enable row level security;alter table portfolios enable row level security;alter table portfolio_transactions enable row level security;alter table journal_entries enable row level security;alter table alerts enable row level security;alter table notifications enable row level security;alter table saved_screeners enable row level security;alter table user_settings enable row level security;
create policy "own profiles" on profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "own watchlists" on watchlists for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own watchlist items" on watchlist_items for all using(exists(select 1 from watchlists w where w.id=watchlist_id and w.user_id=auth.uid())) with check(exists(select 1 from watchlists w where w.id=watchlist_id and w.user_id=auth.uid()));
create policy "own portfolios" on portfolios for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own transactions" on portfolio_transactions for all using(exists(select 1 from portfolios p where p.id=portfolio_id and p.user_id=auth.uid())) with check(exists(select 1 from portfolios p where p.id=portfolio_id and p.user_id=auth.uid()));
create policy "own journal" on journal_entries for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own alerts" on alerts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own notifications" on notifications for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own screeners" on saved_screeners for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own settings" on user_settings for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
